urlset:
{# Zola 0.17.2's builtin sitemap, with only the experimental route excluded. #}
{%- for sitemap_entry in entries %}
{%- if sitemap_entry.permalink is not ending_with("/megamap/") %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
